/** Frontmost zero crossing along a drawing view's outward normal. */
export function frontSurface(sample:(p:number[])=>number,origin:number[],normal:number[],min:number,max:number,step:number):number|null{
  let outside=max,previous=sample(origin.map((v,i)=>v+max*normal[i]));
  for(let t=max-step;t>=min;t-=step){
    const value=sample(origin.map((v,i)=>v+t*normal[i]));
    if(value>=0&&previous<0){const f=-previous/(value-previous||1);return outside+(t-outside)*f;}
    outside=t;previous=value;
  }
  return null;
}
/** One-sided relief. Negative depths behind the surface cannot affect the back. */
export function surfaceThickness(sample:(p:number[])=>number,origin:number[],normal:number[],front:number,min:number,step:number){
  for(let t=front-step*.5;t>=min;t-=step*.5)if(sample(origin.map((v,i)=>v+t*normal[i]))<0)return Math.max(0,front-t-step*.5);
  return Math.max(0,front-min);
}
export function detailField(footprint:number,relativeDepth:number,depth:number,step:number,raise:boolean,width:number){
  const edge=Math.max(0,Math.min(1,footprint/Math.max(width*.5,step)));
  const height=depth*edge*edge*(3-2*edge);
  return raise?Math.min(footprint,height-relativeDepth,relativeDepth+step*1.5):Math.min(footprint,relativeDepth+height,step-relativeDepth);
}
