import {Matrix3,Matrix4,Vector3} from 'three';

// The brush radius/density are world millimetres; model vertices and layer
// samples stay in object coordinates. Work in world space then return local.
export function sculptSpace(payload:any){
  const values=payload.brush_matrix;
  const matrix=Array.isArray(values)&&values.length===16?new Matrix4().fromArray(values):new Matrix4();
  if(!matrix.elements.every(Number.isFinite)||Math.abs(matrix.determinant())<1e-10)throw Error('Nieprawidłowa skala bryły');
  const inverse=matrix.clone().invert();
  const point=(p:number[])=>new Vector3().fromArray(p).applyMatrix4(matrix).toArray();
  const grab=payload.mode==='grab'||payload.mode==='snake';
  const direction=new Vector3().fromArray(payload.normal??[0,0,1]).applyMatrix3(grab?new Matrix3().setFromMatrix4(matrix):new Matrix3().getNormalMatrix(matrix));
  const depth=Number(payload.maximum_displacement_mm??1)*(grab?direction.length():1);
  return {matrix,inverse,payload:{...payload,normal:direction.normalize().toArray(),maximum_displacement_mm:depth,samples_mm:(payload.samples_mm??[]).map(point),protected_samples_mm:(payload.protected_samples_mm??[]).map(point)}};
}
