import * as THREE from 'three';
/** Surface-facing support: never pull the opposite wall toward the brush. */
export function brushFacingWeight(normal:THREE.Vector3,direction:THREE.Vector3){
  const t=THREE.MathUtils.clamp(normal.dot(direction)/.35,0,1);
  return t*t*(3-2*t);
}
/** Inflate follows the surface; clay deposits a broader stamp along the brush axis. */
export function buildBrushDisplacement(mode:string,normal:THREE.Vector3,direction:THREE.Vector3,depth:number,weight:number,radius:number){
  const support=brushFacingWeight(normal,direction);
  const profile=mode==='clay'?Math.min(1,weight*2):mode==='crease'?weight**3:weight;
  const amount=Math.min(depth,radius*.15)*profile*support*(mode==='deflate'||mode==='crease'?-1:1);
  return (mode==='inflate'||mode==='deflate'||mode==='thicken'?normal:direction).clone().multiplyScalar(amount);
}
export function brushSamples(points:THREE.Vector3[],radius:number){
  if(points.length<2)return points;
  const out=[points[0]],step=Math.max(.01,radius*.12);
  for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i],count=Math.min(256,Math.max(1,Math.ceil(a.distanceTo(b)/step)));for(let j=1;j<=count;j++)out.push(a.clone().lerp(b,j/count));}
  return out;
}
export function brushSearch(samples:THREE.Vector3[],radius:number){
  const cell=Math.max(.001,radius),bins=new Map<string,THREE.Vector3[]>(),key=(x:number,y:number,z:number)=>`${x}:${y}:${z}`;
  for(const p of samples){const k=key(Math.floor(p.x/cell),Math.floor(p.y/cell),Math.floor(p.z/cell)),bucket=bins.get(k)??[];bucket.push(p);bins.set(k,bucket);}
  return (p:THREE.Vector3)=>{const x=Math.floor(p.x/cell),y=Math.floor(p.y/cell),z=Math.floor(p.z/cell);let squared=radius*radius,nearest:THREE.Vector3|undefined;
    for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++)for(let dz=-1;dz<=1;dz++)for(const q of bins.get(key(x+dx,y+dy,z+dz))??[]){const d=p.distanceToSquared(q);if(d<squared){squared=d;nearest=q;}}
    return {distance:Math.sqrt(squared),nearest};
  };
}
export function brushDepth(radius:number){return Math.max(.001,radius*.12);}
export function nearestStrokeDistance(points:THREE.Vector3[]){
  type Node={p:THREE.Vector3;axis:number;left?:Node;right?:Node};
  function build(list:THREE.Vector3[],depth=0):Node|undefined{if(!list.length)return;const axis=depth%3;list.sort((a,b)=>a.getComponent(axis)-b.getComponent(axis));const i=list.length>>1;return {p:list[i],axis,left:build(list.slice(0,i),depth+1),right:build(list.slice(i+1),depth+1)};}
  const root=build([...points]);
  return (p:THREE.Vector3)=>{let best=Infinity;function visit(n?:Node){if(!n)return;best=Math.min(best,p.distanceToSquared(n.p));const delta=p.getComponent(n.axis)-n.p.getComponent(n.axis);visit(delta<0?n.left:n.right);if(delta*delta<best)visit(delta<0?n.right:n.left);}visit(root);return Math.sqrt(best);};
}
