import { createDirectApiFetch } from "./offline-engine";

type WorkerRequest={id:number;input:string;cancel?:boolean;init?:{method?:string;headers?:Record<string,string>;body?:string}};

const direct=createDirectApiFetch();
const cancelled=new Set<number>();
self.addEventListener("message",async event=>{
  const request=event.data as WorkerRequest;
  if(request.cancel){cancelled.add(request.id);return;}
  try{
    const response=await direct(request.input,{method:request.init?.method,headers:request.init?.headers,body:request.init?.body});
    const body=await response.text();
    if(cancelled.delete(request.id))return;
    self.postMessage({id:request.id,status:response.status,body});
  }catch(error){if(cancelled.delete(request.id))return;self.postMessage({id:request.id,status:500,error:error instanceof Error?error.message:String(error)});}
});
