import * as THREE from "three";
export function exactFaceSelection(vertices:number[][],faces:number[][],targets:number[][][]){
  const points=vertices.map(p=>new THREE.Vector3().fromArray(p)),tolerance=Math.max(1e-5,new THREE.Box3().setFromPoints(points).getSize(new THREE.Vector3()).length()*2e-7);
  const cell=(p:THREE.Vector3)=>p.toArray().map(v=>Math.floor(v/tolerance)),buckets=new Map<string,number[]>();
  points.forEach((p,i)=>{const key=cell(p).join(":");buckets.set(key,[...(buckets.get(key)??[]),i]);});
  const lookup=(raw:number[])=>{const p=new THREE.Vector3().fromArray(raw),c=cell(p);let best=-1,distance=tolerance*tolerance;
    for(let x=-1;x<=1;x++)for(let y=-1;y<=1;y++)for(let z=-1;z<=1;z++)for(const i of buckets.get([c[0]+x,c[1]+y,c[2]+z].join(":"))??[]){const d=p.distanceToSquared(points[i]);if(d<=distance){distance=d;best=i;}}return best;
  };
  const faceKey=(t:number[])=>[...t].sort((a,b)=>a-b).join(":"),byKey=new Map(faces.map((t,i)=>[faceKey(t),i])),selected=new Set<number>();
  for(const triangle of targets){const indices=triangle.map(lookup),face=byKey.get(faceKey(indices));if(indices.includes(-1)||face===undefined)throw new Error("Zaznaczona powierzchnia nie odpowiada aktualnej siatce — zaznacz ją ponownie.");selected.add(face);}
  if(!selected.size)throw new Error("Brak zaznaczonej powierzchni");return selected;
}
