import * as THREE from 'three';

// A straight convex edge: remove the corner outside a circle tangent to its
// two incident planes. No global subdivision or normal-based denting.
export function filletCut(w:any,d:{v:number[][];f:number[][]},edge:number[][],radius:number,segments=12,profile='round'){
  if(!Number.isFinite(radius)||radius<=0)throw Error('Promień musi być dodatnią liczbą w mm');
  const points=d.v.map(p=>new THREE.Vector3(...p)),a=new THREE.Vector3(...edge[0]),b=new THREE.Vector3(...edge[1]);
  const axis=b.clone().sub(a),length=axis.length();if(length<1e-6)throw Error('Krawędź jest zbyt krótka');axis.normalize();
  const tolerance=Math.max(1e-5,new THREE.Box3().setFromPoints(points).getSize(new THREE.Vector3()).length()*1e-6);
  const onLine=(p:THREE.Vector3)=>p.clone().sub(a).cross(axis).length()<tolerance;
  const sides:THREE.Vector3[]=[],normals:THREE.Vector3[]=[];let min=0,max=length;
  let signedVolume=0;for(const [i,j,k] of d.f)signedVolume+=points[i].dot(points[j].clone().cross(points[k]));
  for(const f of d.f){const q=f.map(i=>points[i]),on=q.filter(onLine);if(on.length!==2)continue;
    const off=q.find(p=>!onLine(p))!,inward=off.clone().sub(on[0]);inward.addScaledVector(axis,-inward.dot(axis)).normalize();
    if(!sides.some(s=>s.dot(inward)>.99999)){sides.push(inward);normals.push(q[1].clone().sub(q[0]).cross(q[2].clone().sub(q[0])).normalize().multiplyScalar(Math.sign(signedVolume)||1));}
    for(const p of on){const t=p.clone().sub(a).dot(axis);min=Math.min(min,t);max=Math.max(max,t);}
  }
  if(sides.length!==2)throw Error('Zaokrąglenie wymaga prostej krawędzi między dwiema płaskimi ścianami');
  const [u,v]=sides,theta=Math.acos(THREE.MathUtils.clamp(u.dot(v),-1,1));
  if(normals[0].dot(v)>1e-5||normals[1].dot(u)>1e-5)throw Error('Wklęsłe krawędzie nie są jeszcze obsługiwane');
  if(theta<.08||theta>Math.PI-.08)throw Error('Wybierz ostrą krawędź bryły, nie przekątną ściany');
  const tangent=radius/Math.tan(theta/2),center=u.clone().add(v).normalize().multiplyScalar(radius/Math.sin(theta/2));
  const y=axis.clone().cross(u),cy=center.dot(y),vy=v.dot(y);
  const polygon=[[0,0],[tangent,0],[center.dot(u),cy],[tangent*v.dot(u),tangent*vy]];
  let section=new w.CrossSection([polygon],'EvenOdd');
  if(profile==='linear'){section.delete();section=new w.CrossSection([[polygon[0],polygon[1],polygon[3]]],'EvenOdd');}
  else {const disk=w.CrossSection.circle(radius,Math.max(32,segments*4)).translate([center.dot(u),cy]);const cut=section.subtract(disk);section.delete();disk.delete();section=cut;}
  const local=section.extrude(max-min+2*tolerance),matrix=new THREE.Matrix4().makeBasis(u,y,axis).setPosition(a.clone().addScaledVector(axis,min-tolerance));
  const cutter=local.transform(matrix.toArray());local.delete();section.delete();
  return cutter;
}
