export type BendFrame={axis:number;toward:number;center:number[];length:number;angle:number};
/** Cylindrical bend around a shared world-space frame; no camera dependency. */
export function bendPoint(point:number[],p:BendFrame):[number,number,number]{
  if(![0,1,2].includes(p.axis)||![0,1,2].includes(p.toward)||p.axis===p.toward||!Number.isFinite(p.length)||p.length<=0||!Number.isFinite(p.angle)||Math.abs(p.angle)>270||p.center.length!==3||p.center.some(v=>!Number.isFinite(v)))throw Error('Sprawdź oś, długość i kąt zagięcia (±270°)');
  const out=[...point] as [number,number,number];
  if(Math.abs(p.angle)<1e-6)return out;
  const radius=p.length/(p.angle*Math.PI/180),x=point[p.axis]-p.center[p.axis],y=point[p.toward]-p.center[p.toward],theta=x/radius;
  if(Math.abs(y/radius)>=.9)throw Error('Promień zagięcia jest za mały dla grubości bryły. Zmniejsz kąt.');
  out[p.axis]=p.center[p.axis]+(radius-y)*Math.sin(theta);
  out[p.toward]=p.center[p.toward]+radius*(1-Math.cos(theta))+y*Math.cos(theta);
  return out;
}
