/*
 * Small TypeScript bridge for the official QuadriFlow C++ solver compiled to
 * WebAssembly.  The bridge deliberately has no Three.js dependency: the
 * offline engine can use it from its worker and the returned quad topology is
 * converted to manifold triangles at the API boundary.
 */
export type QuadriFlowNativeInput = {
  vertices: Float64Array;
  triangles: Int32Array;
  targetFaces: number;
  preserveSharp: boolean;
  preserveBoundary: boolean;
};

export type QuadriFlowNativeOutput = {
  vertices: Float64Array;
  quads: Int32Array;
};

type QuadriFlowModule = {
  _malloc(size: number): number;
  _free(pointer: number): void;
  _quadriflow_run(vertices: number, vertexCount: number, triangles: number, triangleCount: number, targetFaces: number, preserveSharp: number, preserveBoundary: number, outVertices: number, outVertexCount: number, outQuads: number, outQuadCount: number): number;
  _quadriflow_free(pointer: number): void;
  HEAPF64: Float64Array;
  HEAP32: Int32Array;
};

let modulePromise: Promise<QuadriFlowModule> | null = null;

function nativeAssetUrl() {
  // Vite puts worker chunks under /assets while public/ files remain at the
  // deployment root.  This works for both a relative GitHub Pages base and
  // the Vite dev server without hard-coding the repository name.
  const locationHref = String((globalThis as { location?: { href?: string } }).location?.href ?? "");
  const assetMarker = "/assets/";
  const root = assetMarker && locationHref.includes(assetMarker)
    ? locationHref.slice(0, locationHref.indexOf(assetMarker) + 1)
    : locationHref.replace(/\/src\/[^/]*$/, "/").replace(/\/assets\/[^/]*$/, "/");
  return new URL("quadriflow-native.js", root || import.meta.url).toString();
}

async function loadNativeModule() {
  if (!modulePromise) {
    modulePromise = (async () => {
      const imported = await import(/* @vite-ignore */ nativeAssetUrl()) as { default?: (options?: Record<string, unknown>) => Promise<QuadriFlowModule> | QuadriFlowModule };
      if (typeof imported.default !== "function") throw new Error("QuadriFlow WASM factory is missing");
      const module = await imported.default({ locateFile: (file: string) => new URL(file, nativeAssetUrl()).toString() });
      return module;
    })();
  }
  return modulePromise;
}

function slot(module: QuadriFlowModule, pointer: number) {
  return module.HEAP32[pointer >>> 2] >>> 0;
}

export async function runQuadriFlowNative(input: QuadriFlowNativeInput): Promise<QuadriFlowNativeOutput> {
  if (!input.vertices.length || input.triangles.length < 3) throw new Error("QuadriFlow wymaga niepustej siatki");
  const module = await loadNativeModule();
  const vertexBytes = input.vertices.byteLength;
  const triangleBytes = input.triangles.byteLength;
  const vertexPtr = module._malloc(vertexBytes);
  const trianglePtr = module._malloc(triangleBytes);
  const outVertexPtr = module._malloc(4);
  const outVertexCount = module._malloc(4);
  const outQuadPtr = module._malloc(4);
  const outQuadCount = module._malloc(4);
  try {
    module.HEAPF64.set(input.vertices, vertexPtr >>> 3);
    module.HEAP32.set(input.triangles, trianglePtr >>> 2);
    const status = module._quadriflow_run(
      vertexPtr, input.vertices.length / 3, trianglePtr, input.triangles.length / 3,
      Math.max(4, Math.floor(input.targetFaces)), input.preserveSharp ? 1 : 0,
      input.preserveBoundary ? 1 : 0, outVertexPtr, outVertexCount, outQuadPtr, outQuadCount,
    );
    if (status !== 0) throw new Error(`QuadriFlow WASM zakończył się kodem ${status}`);
    const outputVerticesPointer = slot(module, outVertexPtr);
    const outputVertexCount = slot(module, outVertexCount);
    const outputQuadsPointer = slot(module, outQuadPtr);
    const outputQuadCount = slot(module, outQuadCount);
    if (!outputVerticesPointer || !outputQuadsPointer || outputVertexCount < 4 || outputQuadCount < 1) throw new Error("QuadriFlow nie zwrócił poprawnej siatki quad");
    const vertices = module.HEAPF64.slice(outputVerticesPointer >>> 3, (outputVerticesPointer >>> 3) + outputVertexCount * 3);
    const quads = module.HEAP32.slice(outputQuadsPointer >>> 2, (outputQuadsPointer >>> 2) + outputQuadCount * 4);
    module._quadriflow_free(outputVerticesPointer);
    module._quadriflow_free(outputQuadsPointer);
    return { vertices, quads };
  } finally {
    module._free(vertexPtr); module._free(trianglePtr); module._free(outVertexPtr);
    module._free(outVertexCount); module._free(outQuadPtr); module._free(outQuadCount);
  }
}

export function quadriFlowNativeLoaded() { return modulePromise !== null; }
