/** Source constraints in part-local coordinates. Generated meshes are NOT sources. */
export type Vec2=[number,number];
export type Vec3=[number,number,number];
export type SketchFrame={origin:Vec3;u:Vec3;v:Vec3;normal:Vec3;mmPerUnit:number};
export type CameraSnapshot={projection:'orthographic';cameraToWorld:number[];projectionMatrix:number[];worldToPart:number[]};
type ConstraintBase={id:string;name:string;enabled:boolean;weight:number;toleranceMm:number;frame:SketchFrame;camera:CameraSnapshot;points:Vec2[];surface:'smooth'|'hard';sharpSegments:number[]};
export type SketchConstraint=ConstraintBase&(
  {kind:'silhouette';closed:true}|
  {kind:'section';closed:true}|
  {kind:'detail';closed:boolean;operation:'raise'|'recess'|'groove'|'through-hole';depthMm:number;placement?:'plane'|'surface';widthMm?:number}
);
export type SketchVolumeDocument={schema:'skaner.sketch-volume';version:1;id:string;revision:number;mode:'organic'|'cad';singleView:{interpretation:'inflate'|'extrude';depthMm:number;bulge:number;symmetry:'none'|'depth'};constraints:SketchConstraint[]};
const dot=(a:Vec3,b:Vec3)=>a[0]*b[0]+a[1]*b[1]+a[2]*b[2];
const cross=(a:Vec3,b:Vec3):Vec3=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
const finite=(x:unknown):x is number=>typeof x==='number'&&Number.isFinite(x);
const vector=(x:unknown,n:number)=>Array.isArray(x)&&x.length===n&&x.every(finite);
const record=(x:unknown):x is Record<string,any>=>!!x&&typeof x==='object'&&!Array.isArray(x);
function validFrame(f:unknown):f is SketchFrame{
  if(!record(f)||!['origin','u','v','normal'].every(k=>vector(f[k],3))||!finite(f.mmPerUnit)||f.mmPerUnit<=0)return false;
  return [f.u,f.v,f.normal].every(a=>Math.abs(dot(a,a)-1)<1e-6)&&Math.abs(dot(f.u,f.v))<1e-6&&dot(cross(f.u,f.v),f.normal)>1-1e-6;
}
function validConstraint(c:unknown):c is SketchConstraint{
  if(!record(c)||typeof c.id!=='string'||!c.id||typeof c.name!=='string'||typeof c.enabled!=='boolean'||!finite(c.weight)||c.weight<0||c.weight>1||!finite(c.toleranceMm)||c.toleranceMm<=0||!validFrame(c.frame))return false;
  if(!record(c.camera)||c.camera.projection!=='orthographic'||!['cameraToWorld','projectionMatrix','worldToPart'].every(k=>vector(c.camera[k],16)))return false;
  if(!['smooth','hard'].includes(c.surface)||typeof c.closed!=='boolean'||!Array.isArray(c.points)||c.points.length<(c.closed?3:2)||c.points.length>10000||!c.points.every((p:unknown)=>vector(p,2)))return false;
  if(!Array.isArray(c.sharpSegments)||c.sharpSegments.some((i:unknown)=>!Number.isInteger(i)||Number(i)<0||Number(i)>=c.points.length-(c.closed?0:1)))return false;
  if(c.kind==='silhouette'||c.kind==='section')return c.closed;
  return c.kind==='detail'&&['raise','recess','groove','through-hole'].includes(c.operation)&&finite(c.depthMm)&&c.depthMm>0&&(c.placement===undefined||['plane','surface'].includes(c.placement))&&(c.widthMm===undefined||finite(c.widthMm)&&c.widthMm>0)&&(c.operation!=='through-hole'||c.closed);
}
export function validSketchVolume(d:unknown):d is SketchVolumeDocument{
  if(!record(d)||d.schema!=='skaner.sketch-volume'||d.version!==1||typeof d.id!=='string'||!d.id||!Number.isSafeInteger(d.revision)||d.revision<0||!['organic','cad'].includes(d.mode))return false;
  const p=d.singleView;if(!record(p)||!['inflate','extrude'].includes(p.interpretation)||!finite(p.depthMm)||p.depthMm<=0||!finite(p.bulge)||p.bulge<0||p.bulge>1||!['none','depth'].includes(p.symmetry))return false;
  if(!Array.isArray(d.constraints)||d.constraints.length>64||!d.constraints.every(validConstraint))return false;
  return new Set(d.constraints.map((c:SketchConstraint)=>c.id)).size===d.constraints.length&&d.constraints.reduce((n:number,c:SketchConstraint)=>n+c.points.length,0)<=100000;
}
export function cloneSketchVolume(d:SketchVolumeDocument):SketchVolumeDocument{return structuredClone(d);}
export function setSketchConstraint(d:SketchVolumeDocument,c:SketchConstraint):SketchVolumeDocument{
  const next=cloneSketchVolume(d),index=next.constraints.findIndex(item=>item.id===c.id);
  if(index<0)next.constraints.push(structuredClone(c));else next.constraints[index]=structuredClone(c);
  next.revision++;if(!validSketchVolume(next))throw new Error('Nieprawidłowy dokument szkiców bryły');return next;
}
export function sketchToLocal(frame:SketchFrame,p:Vec2,depthMm=0):Vec3{
  return frame.origin.map((o,i)=>o+frame.mmPerUnit*(p[0]*frame.u[i]+p[1]*frame.v[i])+depthMm*frame.normal[i]) as Vec3;
}
export function localToSketch(frame:SketchFrame,p:Vec3):{point:Vec2;depthMm:number}{
  const delta=p.map((v,i)=>v-frame.origin[i]) as Vec3;
  return {point:[dot(delta,frame.u)/frame.mmPerUnit,dot(delta,frame.v)/frame.mmPerUnit],depthMm:dot(delta,frame.normal)};
}
export type RangeConflict={a:string;b:string;axis:Vec3;rangeA:[number,number];rangeB:[number,number];errorMm:number};
/** Necessary condition only. An empty report does NOT certify compatible silhouettes. */
export function silhouetteRangeConflicts(d:SketchVolumeDocument):RangeConflict[]{
  if(!validSketchVolume(d))throw new Error('Nieprawidłowy dokument szkiców bryły');
  const silhouettes=d.constraints.filter(c=>c.kind==='silhouette'&&c.enabled&&c.weight>0),conflicts:RangeConflict[]=[];
  const range=(c:SketchConstraint,axis:Vec3):[number,number]=>{let min=Infinity,max=-Infinity;for(const p of c.points){const x=dot(sketchToLocal(c.frame,p),axis);min=Math.min(min,x);max=Math.max(max,x);}return[min,max];};
  for(let i=0;i<silhouettes.length;i++)for(let j=i+1;j<silhouettes.length;j++){
    const a=silhouettes[i],b=silhouettes[j],shared=cross(a.frame.normal,b.frame.normal),length=Math.hypot(...shared);
    const axes:Vec3[]=length<1e-6?[a.frame.u,a.frame.v]:[shared.map(x=>x/length) as Vec3];
    for(const axis of axes){const rangeA=range(a,axis),rangeB=range(b,axis),errorMm=Math.max(Math.abs(rangeA[0]-rangeB[0]),Math.abs(rangeA[1]-rangeB[1]));if(errorMm>a.toleranceMm+b.toleranceMm)conflicts.push({a:a.id,b:b.id,axis,rangeA,rangeB,errorMm});}
  }
  return conflicts;
}
export function isCurrentSketchResult(d:SketchVolumeDocument,result:{documentId:string;revision:number}){return result.documentId===d.id&&result.revision===d.revision;}
