type V3=[number,number,number];
export type RepairMesh={v:V3[];f:V3[]};
/** Conservative topology repair. Never caps holes or moves coordinates. */
export function repairMesh(input:RepairMesh,weld=false){
  const vertices:V3[]=[],mapping:number[]=[],positions=new Map<string,number>();
  for(const point of input.v){
    if(!point.every(Number.isFinite))throw new Error('Siatka ma nieprawidłowe współrzędne.');
    const key=point.join(':');let index=weld?positions.get(key):undefined;
    if(index===undefined){index=vertices.length;vertices.push([...point]);if(weld)positions.set(key,index);}
    mapping.push(index);
  }
  let degenerate=0,duplicates=0;const seen=new Set<string>(),faces:V3[]=[];
  for(const raw of input.f){
    if(raw.some(i=>!Number.isInteger(i)||i<0||i>=mapping.length))throw new Error('Nieprawidłowy indeks trójkąta.');
    const f=raw.map(i=>mapping[i]) as V3,[a,b,c]=f.map(i=>vertices[i]);
    const u=b.map((x,i)=>x-a[i]),v=c.map((x,i)=>x-a[i]);
    const area=(u[1]*v[2]-u[2]*v[1])**2+(u[2]*v[0]-u[0]*v[2])**2+(u[0]*v[1]-u[1]*v[0])**2;
    if(new Set(f).size<3||area===0){degenerate++;continue;}
    const key=[...f].sort((a,b)=>a-b).join(':');if(seen.has(key)){duplicates++;continue;}seen.add(key);faces.push(f);
  }
  const edges=new Map<string,{face:number;sign:number}[]>();
  faces.forEach((f,face)=>{for(let j=0;j<3;j++){const a=f[j],b=f[(j+1)%3],key=a<b?`${a}:${b}`:`${b}:${a}`,uses=edges.get(key)??[];uses.push({face,sign:a<b?1:-1});edges.set(key,uses);}});
  const adjacency=faces.map(()=>[] as {face:number;flip:boolean}[]);let boundary=0,nonmanifold=0;
  for(const uses of edges.values()){if(uses.length===1)boundary++;else if(uses.length>2)nonmanifold++;else{const [a,b]=uses;adjacency[a.face].push({face:b.face,flip:a.sign===b.sign});adjacency[b.face].push({face:a.face,flip:a.sign===b.sign});}}
  const flips=new Int8Array(faces.length).fill(-1),components:number[][]=[];let conflicts=0;
  for(let seed=0;seed<faces.length;seed++){if(flips[seed]!==-1)continue;const queue=[seed];flips[seed]=0;for(let head=0;head<queue.length;head++){const current=queue[head];for(const n of adjacency[current]){const expected=flips[current]^(n.flip?1:0);if(flips[n.face]===-1){flips[n.face]=expected;queue.push(n.face);}else if(flips[n.face]!==expected)conflicts++;}}components.push(queue);}
  // Reverse whole closed components only; open surfaces have no inside/outside.
  const openFaces=new Set<number>();for(const uses of edges.values())if(uses.length!==2)for(const u of uses)openFaces.add(u.face);
  let reoriented=0;
  for(const component of components){let volume=0;for(const i of component){const f=faces[i],[a,b,c]=f.map(j=>vertices[j]);volume+=(flips[i]?-1:1)*(a[0]*(b[1]*c[2]-b[2]*c[1])+a[1]*(b[2]*c[0]-b[0]*c[2])+a[2]*(b[0]*c[1]-b[1]*c[0]));}if(volume<0&&!component.some(i=>openFaces.has(i)))for(const i of component)flips[i]^=1;}
  faces.forEach((f,i)=>{if(flips[i]){[f[1],f[2]]=[f[2],f[1]];reoriented++;}});
  const used=new Map<number,number>(),v:V3[]=[];
  const f=faces.map(face=>face.map(i=>{if(!used.has(i)){used.set(i,v.length);v.push(vertices[i]);}return used.get(i)!;}) as V3);
  return {mesh:{v,f},report:{removed_degenerate:degenerate,removed_duplicates:duplicates,welded_vertices:input.v.length-vertices.length,removed_unused:vertices.length-v.length,reoriented_faces:reoriented,boundary_edges:boundary,nonmanifold_edges:nonmanifold,orientation_conflicts:conflicts,components:components.length,holes_filled:0}};
}
